i='TCS-3117';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 1.3 and Conjecture 1, pp. 60:3–60:4; Section 2, Definition 4, pp. 60:5–60:6 (branching programs, success probability and randomized learners).'
